const D = { segments:6, density:.5, energy:.6, speed:1, hue:300, scale:1, x:.5, y:.5, style:'stained', act:'spin', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v)), frc=v=>v-Math.floor(v), TAU=Math.PI*2, md=(a,n)=>((a%n)+n)%n;
const fr=(i)=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const style=P.style;
let segs=Math.round(clp(P.segments,2,12)); if(segs%2) segs+=1; segs=clp(segs,2,12);
const ang=TAU/segs;
const dens=clp(P.density,0,1), en=clp(P.energy,0,1), spd=clp(P.speed,.1,6), sc=clp(P.scale,.3,3);
const cx=P.x*W, cy=P.y*Hh;
const RR=Math.hypot(Math.max(cx,W-cx),Math.max(cy,Hh-cy))*1.06*Math.max(0.5,sc);

const isNeon=style==='neon', isChrome=style==='chrome', isWire=style==='wire', isInk=style==='ink';

// seeded motif field (local wedge coords), rebuilt on seed/style/density change
const M=Math.floor(5+16*dens), dB=Math.round(dens*5);
if(S.seedUsed!==P.seed || S.mKey!==style+'|'+dB+'|'+segs){
  S.seedUsed=P.seed; S.mKey=style+'|'+dB+'|'+segs; S.mot=[];
  for(let i=0;i<M;i++) S.mot.push({ rr:0.10+0.86*fr(i*1.7), aa:fr(i*2.3), sz:0.28+0.95*fr(i*3.1), hOff:(fr(i*4.7)-0.5)*90, kind:Math.floor(fr(i*5.3)*3), rot:fr(i*6.1)*TAU, spin:(fr(i*7)-0.5)*1.6 });
}

// live drivers — real-time drift never re-phases; audio blends on top
const act=P.act;
const drift = K.t*0.14*spd + (act==='breathe'? 0.5*Math.sin(K.t*0.35): 0) + K.beat*0.02*spd;
const pulse = 1 + 0.10*K.swell + 0.28*A.rms + 0.06*Math.sin(K.t*0.6) + (act==='bloom'? 0.12*Math.sin(K.t*0.12):0);
const hueBase = P.hue + K.t*(act==='bloom'?11:5);

// base tone per style (fills each wedge so mandala is opaque over the bed)
let bH=P.hue,bS=60,bB=26,bA=90;
if(isNeon){ bH=md(P.hue+200,360); bS=50; bB=8; bA=94; }
else if(isChrome){ bH=P.hue; bS=18; bB=16; bA=92; }
else if(isWire){ bH=md(P.hue+180,360); bS=30; bB=6; bA=96; }
else if(isInk){ bH=P.hue; bS=8; bB=90; bA=90; }

function motif(){
  const addGlow=isNeon||isChrome;
  if(addGlow) blendMode(ADD); else blendMode(BLEND);
  for(let i=0;i<S.mot.length;i++){
    const m=S.mot[i];
    const a=m.aa*ang;
    const rad=m.rr*RR*pulse*(0.9+0.18*Math.sin(K.t*0.5+i));
    const x=Math.cos(a)*rad, y=Math.sin(a)*rad;
    const sz=m.sz*RR*0.11*(0.75+0.5*Math.sin(K.t*0.7+i*1.3)+0.5*A.bass*en);
    const h=md(hueBase+m.hOff+rad/RR*46,360);
    push(); translate(x,y); rotate(m.rot+drift*(1+m.spin));
    if(isWire){
      noFill(); stroke(h,40,100,70); strokeWeight((0.6+1.1*en)*sc);
      const kk=3+((m.kind+3)%3); beginShape();
      for(let s=0;s<=kk;s++){ const aa2=s/kk*TAU; vertex(Math.cos(aa2)*sz,Math.sin(aa2)*sz); } endShape(CLOSE);
      line(-sz,0,sz,0); line(0,-sz,0,sz);
    } else if(isNeon){
      noFill(); stroke(h,80,100,22); strokeWeight(sz*0.5); arc(0,0,sz*2,sz*2,0,TAU*(0.5+0.5*fr(i)));
      stroke(h,55,100,80); strokeWeight(1.4*sc); arc(0,0,sz*2,sz*2,0,TAU*(0.5+0.5*fr(i)));
    } else if(isChrome){
      noFill(); strokeWeight(1.6*sc);
      for(let r2=0;r2<3;r2++){ stroke(md(h+r2*40,360),40,100,54); circle(0,0,sz*2*(0.4+r2*0.32)); }
    } else if(isInk){
      noStroke(); fill(md(h,360),clp(bS+30,0,100),22,clp(40+40*fr(i),0,80)); circle(0,0,sz*(1+0.4*Math.sin(K.t+i)));
      fill(0,0,10,26); for(let d=0;d<3;d++){ const da=fr(i*9+d)*TAU, dr=sz*0.7*fr(i*3+d); circle(Math.cos(da)*dr,Math.sin(da)*dr,sz*0.28*fr(i+d)); }
    } else { // stained glass: jewel fill + dark leading
      const kk=3+m.kind; fill(h,clp(bS+25,0,100),clp(bB+55,0,96),94);
      stroke(0,0,6,90); strokeWeight((1.4+1.6*en)*sc);
      beginShape(); for(let s=0;s<kk;s++){ const aa2=s/kk*TAU+m.rot; vertex(Math.cos(aa2)*sz,Math.sin(aa2)*sz);} endShape(CLOSE);
    }
    pop();
  }
  blendMode(BLEND);
}

// central rosette (drawn once per wedge for a crisp core)
function core(){
  const cr=RR*0.10*(0.9+0.12*K.swell+0.3*A.bass*en);
  if(isWire){ noFill(); stroke(md(hueBase,360),40,100,80); strokeWeight(1.2*sc); circle(0,0,cr*2); }
  else if(isNeon||isChrome){ blendMode(ADD); noStroke(); fill(md(hueBase,360),40,100,30); circle(0,0,cr*2.2); blendMode(BLEND); }
  else { noStroke(); fill(md(hueBase,360),clp(bS,0,100),clp(bB+40,0,96),90); circle(0,0,cr*2); }
}

for(let i=0;i<segs;i++){
  push();
  translate(cx,cy);
  if(i%2===0) rotate(ang*i); else { rotate(ang*(i+1)); scale(1,-1); }
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.moveTo(0,0);
  drawingContext.lineTo(RR,0);
  drawingContext.arc(0,0,RR,0,ang);
  drawingContext.closePath();
  drawingContext.clip();
  noStroke(); fill(bH,bS,bB,bA); rect(-RR,-RR,2*RR,2*RR);
  motif();
  core();
  drawingContext.restore();
  pop();
}

blendMode(BLEND); drawingContext.shadowBlur=0; noStroke(); noTint();
